#include <iostream>
#include <cmath>

int main() {
    std::cout << (int)sqrt(25.0) << "\n";
    std::cout << (int)pow(2.0, 8.0) << "\n";
    std::cout << (int)floor(7.8) << "\n";
    return 0;
}
